FOR UPDATE

SELECT

FROM dreams

    workspace_uuid = #{params.WorkspaceUUID}
    AND archived_at IS NULL

        AND (
            created_at < #{params.CursorCreatedAt}
            OR (created_at = #{params.CursorCreatedAt} AND uuid < #{params.CursorUUID})
        )


ORDER BY created_at DESC, uuid DESC
LIMIT #{params.Limit}

mapper.update:
UPDATE dreams
SET status = #{params.Status},
    updated_at = NOW()
WHERE workspace_uuid = #{params.WorkspaceUUID}
AND external_id = #{params.ExternalID}
AND archived_at IS NULL
AND status IN ('pending', 'running')
AND status != #{params.Status}
